          {jahre.map((j) => (
            <span key={j} className={cn("absolute whitespace-nowrap", j === 0 ? "" : j * 12 >= monate ? "-translate-x-full" : "-translate-x-1/2")} style={{ left: pct(j * 12) }}>
              {j === 0 ? "Start" : `${j} J.`}
            </span>
          ))}
        </div>
      </div>
      <ol className="space-y-4 md:space-y-2.5">
